-- Merge of module21-contact-center into main: both lines of work redefined these MySQL ENUM columns
-- with only their own new values (Production/Procurement vs Finance/Payments/Assets/Field Service/
-- Contracts). Whichever ALTER ran last dropped the other side's values, so restate the full union.
ALTER TABLE `stock_movements` MODIFY `kind` ENUM('purchase', 'sale', 'wastage', 'adjustment', 'return', 'transfer_out', 'transfer_in', 'production_consume', 'production_output', 'maintenance', 'field_service') NOT NULL;

ALTER TABLE `action_item_states` MODIFY `type` ENUM('complaint', 'low_stock', 'overdue_credit', 'unreplied_review', 'commerce', 'procurement_request', 'finance_approval', 'payment_approval', 'payment_dispute_due', 'payment_failed', 'asset_pm_overdue', 'asset_down_critical', 'asset_wo_approval', 'field_approval', 'field_sla_breach', 'field_unassigned_urgent', 'contract_approval', 'contract_expiring', 'contract_obligation_overdue', 'contract_signature_issue') NOT NULL;

